	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _kpgzlt(d)
	d = d:gsub("[^" .. _ccluuw .. "=]", "")
